import{_ as t,o as a,c as n,ah as o}from"./chunks/framework.Bja9t6Wf.js";const u=JSON.parse(`{"title":"Research: The Benko Connection (Horten's Legacy at Signa)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/die-benko-verbindung.md","filePath":"en/recherche/die-benko-verbindung.md"}`),r={name:"en/recherche/die-benko-verbindung.md"};function i(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="research-the-benko-connection-horten-s-legacy-at-signa" tabindex="-1">Research: The Benko Connection (Horten&#39;s Legacy at Signa) <a class="header-anchor" href="#research-the-benko-connection-horten-s-legacy-at-signa" aria-label="Permalink to &quot;Research: The Benko Connection (Horten&#39;s Legacy at Signa)&quot;">​</a></h1><p><strong>From Department Store King to Real Estate Speculator: The Circle Closes.</strong></p><p>In our mockumentary, René Benko is the legitimate, if tragic, descendant of the &quot;Horten System.&quot; While Helmut Horten laid the physical foundation of German retail through &quot;Aryanization&quot; and expansion, Benko used the remains of this empire for the largest real estate speculation in post-war history.</p><hr><h2 id="the-historical-line" tabindex="-1">The Historical Line <a class="header-anchor" href="#the-historical-line" aria-label="Permalink to &quot;The Historical Line&quot;">​</a></h2><h3 id="_1-from-horten-to-galeria" tabindex="-1">1. From Horten to Galeria <a class="header-anchor" href="#_1-from-horten-to-galeria" aria-label="Permalink to &quot;1. From Horten to Galeria&quot;">​</a></h3><p>Helmut Horten built <strong>Horten AG</strong> on the injustice of the 1930s. After his withdrawal, the chain was taken over by <strong>Kaufhof</strong> in 1994. The Horten brand disappeared, but the locations (often in prime city center spots) remained.</p><h3 id="_2-benko-s-takeover" tabindex="-1">2. Benko&#39;s Takeover <a class="header-anchor" href="#_2-benko-s-takeover" aria-label="Permalink to &quot;2. Benko&#39;s Takeover&quot;">​</a></h3><p>René Benko and his <strong>Signa Group</strong> bought Karstadt (2014) and Galeria Kaufhof (2018/2019) and merged them into <strong>Galeria Karstadt Kaufhof (GKK)</strong>. With this, Benko controlled almost the entire legacy of the great German department store era – including many former Horten locations.</p><hr><h2 id="the-signa-system-modern-pointillism" tabindex="-1">The Signa System: Modern Pointillism? <a class="header-anchor" href="#the-signa-system-modern-pointillism" aria-label="Permalink to &quot;The Signa System: Modern Pointillism?&quot;">​</a></h2><p>Benko perfected a method we could call &quot;Real Estate Pointillism&quot;:</p><ul><li><strong>The Method:</strong> He separated the trade (the department stores) from the stones (the real estate).</li><li><strong>The Effect:</strong> The department stores had to pay extremely high rents to Signa Prime. This drained liquidity from the trade, while the value of the properties in Signa&#39;s books was artificially inflated to generate new loans.</li><li><strong>The Result:</strong> A house of cards built on billions that only appeared stable through many small, perfectly placed valuations and loans – until interest rates rose.</li></ul><hr><h2 id="the-downfall-2023–2025" tabindex="-1">The Downfall (2023–2025) <a class="header-anchor" href="#the-downfall-2023–2025" aria-label="Permalink to &quot;The Downfall (2023–2025)&quot;">​</a></h2><p>At the end of 2023, the Signa empire collapsed. It is the largest corporate bankruptcy in Austrian history.</p><ul><li><strong>Status 2026:</strong> René Benko has been convicted of damaging creditors and is in legal disputes over the remains of his private assets.</li></ul><hr><p><em>Sources: Analysis of the Signa insolvency (Handelsblatt, Standard), historical data on Horten AG, court reports 2025.</em></p>',19)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
